    isHighlight: false,
    chips: ["Égypte romaine", "Momie", "Cartonnage doré", "Anubis", "Taureau Apis", "Collier Ousekh", "Musée gréco-romain"],
    deptBanner: "https://lh3.googleusercontent.com/d/1EjnwS0_C2N95iY8FGNrH7N7lHnEDPG57",
