    isHighlight: true,
    chips: ["XXXe dynastie", "Wennefer", "Saqqarah", "Granodiorite", "Livre de l'Amdouat", "Âme-Ba", "Déesse Nout", "Musée du Caire"],
    deptBanner: "https://lh3.googleusercontent.com/d/1HWdb-Q5G3Yz8iCYDdJ3q12BuvTWMARmK",
